//! `levels/ffa_isles.lvl` (generated by `scripts/gen_isles_level.py`): Skyfall Archipelago. Pinned: a hub ziggurat and four
//! spoke islands (y 60 / 45 / 80 / 48 / 50) joined by ramps and stairs into ONE walkable network that holds every spawn, the
//! void under everything, hook / wall-run / jump only places (sanctum, shards, ring), supported pickups, engine limits.

use shinobi_sim::character::{Cfg, PhysicsWorld};
use shinobi_sim::level::{is_floating, parse_level_file, LevelBox, LevelFile};
use shinobi_sim::pvp::KILL_PLANE_Y;
use shinobi_sim::rapier3d::prelude::*;
use shinobi_sim::spawn::far_dist;
use std::collections::{HashMap, VecDeque};

const DECKS: [f32; 5] = [60.0, 45.0, 80.0, 48.0, 50.1];

fn load() -> LevelFile {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/ffa_isles.lvl");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    parse_level_file(&text).unwrap_or_else(|e| panic!("ffa_isles.lvl: {e}"))
}

fn world(l: &LevelFile) -> PhysicsWorld {
    let mut w = PhysicsWorld { bodies: RigidBodySet::new(), colliders: ColliderSet::new(), islands: IslandManager::new(), queries: QueryPipeline::new() };
    l.level.insert_into(&mut w);
    w.queries.update(&w.colliders);
    w
}

fn inside(b: &LevelBox, p: [f32; 3]) -> bool {
    let (s, c) = b.rot_z.sin_cos();
    let (dx, dy) = (p[0] - b.center[0], p[1] - b.center[1]);
    let (u, v) = (dx * c + dy * s, -dx * s + dy * c);
    u.abs() <= b.half[0] && v.abs() <= b.half[1] && (p[2] - b.center[2]).abs() <= b.half[2]
}

/// Top face of one box at (x, z) (rolled boxes give their slope).
fn surface_at(b: &LevelBox, x: f32, z: f32) -> Option<f32> {
    if (z - b.center[2]).abs() > b.half[2] {
        return None;
    }
    let (s, c) = b.rot_z.sin_cos();
    let u = (x - b.center[0] + b.half[1] * s) / c;
    (u.abs() <= b.half[0]).then(|| b.center[1] + u * s + b.half[1] * c)
}

/// Highest surface at (x, z) (rolled boxes give their slope), like looking straight down.
fn top_at(l: &LevelFile, x: f32, z: f32) -> Option<f32> {
    l.level
        .boxes
        .iter()
        .filter(|b| (z - b.center[2]).abs() <= b.half[2])
        .filter_map(|b| {
            let (s, c) = b.rot_z.sin_cos();
            let u = (x - b.center[0] + b.half[1] * s) / c;
            (u.abs() <= b.half[0]).then(|| b.center[1] + u * s + b.half[1] * c)
        })
        .fold(None, |m: Option<f32>, h| Some(m.map_or(h, |m| m.max(h))))
}

fn d3(a: [f32; 3], b: [f32; 3]) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

#[test]
fn archipelago_has_spawns_on_the_hub_and_every_island_and_a_handful_of_pickups() {
    let l = load();
    assert!((250..=480).contains(&l.level.boxes.len()), "{} boxes", l.level.boxes.len());
    assert!((14..=24).contains(&l.level.spawns.len()), "{} spawns", l.level.spawns.len());
    let cubes = l.pickups.iter().filter(|p| p.kind == shinobi_sim::power::PowerKind::None).count();
    assert!((5..=14).contains(&cubes), "{cubes} cubes");
    let yumi = l.pickups.iter().filter(|p| p.kind == shinobi_sim::power::PowerKind::Yumi).count();
    let tags = l.pickups.iter().filter(|p| p.kind == shinobi_sim::power::PowerKind::Tag).count();
    assert!((1..=3).contains(&yumi) && (3..=6).contains(&tags), "{yumi} bows and {tags} tag bags");
    assert!(l.pickups.iter().filter(|p| p.kind != shinobi_sim::power::PowerKind::None).all(|p| p.respawn_secs == 45.0));
    assert!(l.pickups.iter().filter(|p| p.kind == shinobi_sim::power::PowerKind::Yumi).all(|p| p.pos[1] > 85.0), "bows sit high");
    for d in DECKS {
        let n = l.level.spawns.iter().filter(|s| (s[1] - 0.81 - d).abs() < 0.01).count();
        assert!(n >= 3, "deck y = {d}: only {n} spawns");
    }
}

#[test]
fn there_is_no_ground_and_the_kill_plane_is_far_below_the_lowest_body() {
    let l = load();
    assert!(is_floating(&l.level), "no box may reach down toward y = 0");
    let lowest = l.level.boxes.iter().map(|b| b.center[1] - b.half[1]).fold(f32::MAX, f32::min);
    assert!(lowest >= 6.0 && lowest - KILL_PLANE_Y >= 26.0, "lowest body y = {lowest}, kill plane {KILL_PLANE_Y}");
    assert_eq!(l.level.floor_half(), None, "no floor slab");
    let top = l.level.boxes.iter().map(|b| b.center[1] + b.half[1]).fold(0.0, f32::max);
    assert!((150.0..=175.0).contains(&top), "tallest geometry {top} m");
}

#[test]
fn spawns_stand_on_a_deck_clear_of_geometry_and_not_stacked() {
    let l = load();
    let cfg = Cfg::default();
    let reach = cfg.half_height + cfg.radius;
    for s in &l.level.spawns {
        for dy in [-reach + 0.05, -0.3, 0.0, 0.3, reach - 0.05] {
            for (ox, oz) in [(0.0, 0.0), (cfg.radius, 0.0), (-cfg.radius, 0.0), (0.0, cfg.radius), (0.0, -cfg.radius)] {
                let p = [s[0] + ox, s[1] + dy, s[2] + oz];
                assert!(!l.level.boxes.iter().any(|b| inside(b, p)), "spawn {s:?}: capsule point {p:?} is inside geometry");
            }
        }
        let top = top_at(&l, s[0], s[2]).expect("a spawn over void");
        assert!((top - (s[1] - reach)).abs() < 0.1, "spawn {s:?} floats or is buried (surface {top})");
        assert!(DECKS.iter().any(|d| (top - d).abs() < 0.2) || (top - 86.0).abs() < 0.01, "spawn {s:?} is not on a deck (surface {top})");
    }
    let n = l.level.spawns.len();
    let nearest: Vec<f32> = (0..n).map(|i| (0..n).filter(|j| *j != i).map(|j| d3(l.level.spawns[i], l.level.spawns[j])).fold(f32::MAX, f32::min)).collect();
    let min = nearest.iter().copied().fold(f32::MAX, f32::min);
    assert!(min >= 9.0, "two spawns only {min:.1} m apart");
    let max = nearest.iter().copied().fold(0.0, f32::max);
    assert!(max <= 60.0, "a spawn is {max:.1} m from its nearest neighbour");
    let far = far_dist(&l.level.spawns);
    assert!((20.0..=70.0).contains(&far), "preferred respawn distance {far:.1} m");
}

/// Flood the 1 m surface grid (highest surface per cell): neighbours connect when the surface differs by <= 0.5 m. Every
/// spawn lies in ONE component that reaches decks of the hub and all four islands; the sanctum, shards and ring are off it.
#[test]
fn one_walkable_network_joins_every_spawn_and_island_and_the_high_places_stay_disconnected() {
    let l = load();
    let half = 125i32;
    let mut cells: HashMap<(i32, i32), f32> = HashMap::new();
    for x in -half..half {
        for z in -half..half {
            if let Some(t) = top_at(&l, x as f32 + 0.5, z as f32 + 0.5) {
                cells.insert((x, z), t);
            }
        }
    }
    let cell_of = |p: [f32; 3]| (p[0].floor() as i32, p[2].floor() as i32);
    let start = cell_of(l.level.spawns[0]);
    let mut seen: HashMap<(i32, i32), f32> = HashMap::new();
    let mut q = VecDeque::from([start]);
    seen.insert(start, cells[&start]);
    while let Some((x, z)) = q.pop_front() {
        let y = cells[&(x, z)];
        for (dx, dz) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let c = (x + dx, z + dz);
            if seen.contains_key(&c) {
                continue;
            }
            if let Some(&ny) = cells.get(&c) {
                if (ny - y).abs() <= 0.5 {
                    seen.insert(c, ny);
                    q.push_back(c);
                }
            }
        }
    }
    for s in &l.level.spawns {
        assert!(seen.contains_key(&cell_of(*s)), "spawn {s:?} cannot walk to the rest of the archipelago");
    }
    for d in DECKS {
        let n = seen.values().filter(|h| (**h - d).abs() < 0.2).count();
        assert!(n >= 700, "deck y = {d}: only {n} reachable cells");
    }
    // the sanctum (pavilion roof y 150), shards and the stone spiral are real but need the hook / wall-run / jumps
    let sanctum = cells.iter().filter(|(_, h)| (**h - 150.0).abs() < 0.01).count();
    assert!(sanctum >= 300 && cells.iter().filter(|(c, h)| (**h - 150.0).abs() < 0.01 && seen.contains_key(*c)).count() == 0, "sanctum must be off the walkable network");
    let unreached_high = cells.iter().filter(|(c, h)| **h > 40.0 && !seen.contains_key(*c)).count();
    assert!(unreached_high >= 800, "only {unreached_high} high surface cells are off the walkable network");
}

#[test]
fn wall_run_faces_ring_and_the_moon_gate_hangs_clear_of_the_deck() {
    let l = load();
    let tall = l.level.boxes.iter().filter(|b| b.rot_z == 0.0 && b.half[1] * 2.0 >= 40.0 && (b.half[0] >= 2.0 || b.half[2] >= 2.0)).count();
    assert!(tall >= 2, "{tall} boxes with 40 m faces");
    // the ring: sixteen rolled segments, none lower than 6 m over the deck, so you run under it
    let ring: Vec<&LevelBox> = l.level.boxes.iter().filter(|b| b.rot_z != 0.0 && b.half[2] == 3.0 && b.half[1] == 1.4).collect();
    assert!(ring.len() >= 12, "{} ring segments", ring.len());
    for b in &ring {
        assert!(b.center[1] - b.half[1] * 2.0 >= 45.0 + 4.5, "ring segment {b:?} comes down to the deck");
    }
}

#[test]
fn pickups_are_supported_and_not_inside_geometry() {
    let l = load();
    for p in &l.pickups {
        assert!(!l.level.boxes.iter().any(|b| inside(b, p.pos)), "pickup {:?} is inside geometry", p.pos);
        let supported = l.level.boxes.iter().any(|b| surface_at(b, p.pos[0], p.pos[2]).map_or(false, |h| (p.pos[1] - h - 1.0).abs() < 0.3));
        assert!(supported, "pickup {:?} is not ~1 m above a surface", p.pos);
    }
}

#[test]
fn engine_numeric_limits_cover_the_map() {
    let l = load();
    let far = l.level.boxes.iter().map(|b| b.center[0].abs() + b.half[0]).chain(l.level.boxes.iter().map(|b| b.center[2].abs() + b.half[2])).fold(0.0, f32::max);
    assert!(far <= 125.0, "geometry reaches {far} m sideways");
    let q = shinobi_proto::quant::q_pos3([2.0 * far, 175.0, 2.0 * far]);
    let back = shinobi_proto::quant::dq_pos3(q);
    assert!((back[0] - 2.0 * far).abs() < 0.01 && (back[1] - 175.0).abs() < 0.01, "q_pos3 loses precision");
    let w = world(&l);
    assert_eq!(w.colliders.len(), l.level.boxes.len());
}
